//! Handoff lifecycle, including the SAME real user interpretation prefix for A/B/C.
use crate::context::Context;use serde_json::{json,Value};
#[path="dp05_sources.rs"]mod sources;
#[path="dp05_record.rs"]mod record;
#[path="dp05_handoff.rs"]mod handoff;
#[path="dp05_receiver.rs"]mod receiver;
use sources::*;
fn prefix_errors(p:&Value,s:&Sources)->Vec<&'static str>{let mut e=Vec::new();if !matches!(p["action"].as_str(),Some("DELEGATE"|"CLOSE")){e.push("action_missing");}for field in ["purpose","handling","completion_condition"]{if p[field].as_str().unwrap_or("").trim().is_empty(){e.push("purpose_handling_completion_missing");}}
 if p["action"]=="DELEGATE"&&(p["recipient"]!="minimal-draft-agent"||array(&p["targets"]).is_empty()){e.push("unsupported_recipient_or_unresolved_sources");}if !p["targets"].is_array()||!array(&p["targets"]).iter().all(|id|id.as_str().and_then(|id|s.get(id)).map(|s|s["revoked"].as_bool()!=Some(true)).unwrap_or(false)){e.push("invalid_target_or_rights");}e}
pub fn run(input:&Value,ctx:&mut Context)->Result<Value,String>{
 let variant=input["variant"].as_str().unwrap_or("A");let mut sources=Sources::new();let mut state=json!({});let mut record=Value::Null;let mut common_evidence=Vec::new();let mut revision=0;
 let mut outputs=Vec::new();let mut handoffs=Vec::new();let mut receipts=Vec::new();let mut adoptions=Vec::new();
 for event in input["events"].as_array().ok_or("events missing")?{match event["kind"].as_str().unwrap_or(""){
  "source"|"adopt"|"revoke"=>{
   match event["kind"].as_str().unwrap(){
    "source"=>{let s=event["source"].clone();let sid=s["id"].as_str().ok_or("source id")?.to_owned();if sources.get(&sid).map(|old|old["revision"]!=s["revision"]||old["revoked"]!=s["revoked"]).unwrap_or(false){record=Value::Null;ctx.event("DERIVED_STATE_INVALIDATED",&json!({"source_id":sid,"reason":"current_source_or_access_change","before_model_input":true}));}sources.insert(sid,s);common_evidence.retain(|p|valid_span(p,&sources));}
    "adopt"=>{state=event["state"].clone();}
    "revoke"=>{if let Some(s)=sources.get_mut(event["source_id"].as_str().ok_or("revoke id")?){s["revoked"]=json!(true);}record=Value::Null;common_evidence.retain(|p|valid_span(p,&sources));ctx.event("LEASE_REVOKED",event);}
    _=>unreachable!(),
   }ctx.event("PUBLIC_ACTIVITY",event);
   if variant=="B"{revision+=1;let mut prep=ctx.scoped(&[],&[]);prep.event("PREPARATION_START",&json!({"preparation_id":format!("dp05-record-{}",revision),"future_purpose_available":false}));record=record::produce(&mut prep,&sources,&state,&record,event,revision)?;prep.event("PREPARATION_COMPLETE",&json!({"preparation_id":format!("dp05-record-{}",revision)}));}
  }
  "acquire"=>{let(p,d)=selected_reads(ctx,&event["reads"],&sources,"COMMON_ACTUALLY_ACQUIRED");retain_via_original_reads(ctx,&mut common_evidence,&p,&sources);ctx.event("COMMON_EVIDENCE_ACQUIRED",&json!({"trigger":event,"denials":d}));}
  "delegate"|"observe"=>{
   let goal=event["goal_id"].as_str().ok_or("goal_id")?;let stimulus=event["stimulus_id"].as_str().ok_or("stimulus_id")?;let raw=event["utterance"].as_str().ok_or("DP05 requires actual user utterance")?;
   let parents=if variant=="B"{record["producer_node"].as_str().map(|s|vec![s.to_owned()]).unwrap_or_default()}else{Vec::new()};let mut c=ctx.scoped(&[goal.to_owned()],&parents);
   let current_revision=event["delegation_revision"].as_u64().unwrap_or(1);c.capture(stimulus,&json!({"raw_utterance":raw,"goal_id":goal,"revision":current_revision}));
   let prefix_evidence=prefix_original_evidence(&common_evidence,if variant=="B"{&record}else{&Value::Null},&sources);c.logical_buffer("dp05_prefix_original_evidence",serde_json::to_vec(&prefix_evidence).unwrap().len(),"ALLOCATE");
   let payload=json!({"instruction":"Interpret this actual CURRENT user utterance against prior adopted public state and available source catalog. Decide whether the user requests a new downstream draft or explicitly closes without delegation. Return JSON {action:'DELEGATE'|'CLOSE',purpose:string,completion_condition:string,recipient:string|null,targets:[source ID strings],handling:string,artifact_type:string}. Resolve requested purpose, bounded output form/completion, actual source targets and an appropriate recipient from available adapters. The handling is a concrete future intention suitable for a first UI response, not an empty acknowledgement or an unsupported completion claim. Preserve stated restrictions (draft only, no sending, exclusions); prior constraints remain authoritative. Metadata is not source facts; do not invent evidence contents. CLOSE means no new agent work. Do not perform domain planning.","input":{"user_utterance":raw,"prior_adopted_public_state":state,"source_catalog":catalog(&sources),"actual_common_evidence":prefix_evidence,"available_adapters":[{"id":"minimal-draft-agent","capabilities":["bounded_text_draft","source_range_reads"],"no_real_external_actions":true}]},"max_tokens":1400});
   let mut proposal=c.call("dp05_interpret_user_request",&payload)?;let mut errors=prefix_errors(&proposal,&sources);
   if !errors.is_empty(){c.event("ADOPTION_REJECTED",&json!({"proposal":proposal,"errors":errors}));let mut repair=payload.clone();repair["input"]["previous_proposal"]=proposal;repair["input"]["contract_errors"]=json!(errors);proposal=c.call("dp05_repair_user_interpretation",&repair)?;errors=prefix_errors(&proposal,&sources);}
   drop(payload);drop(prefix_evidence);c.logical_buffer("dp05_prefix_original_evidence",0,"RELEASE");
   if !errors.is_empty(){c.fail(goal,&json!({"stimulus_id":stimulus,"reason":"USER_INTERPRETATION_CONTRACT_FAILED","errors":errors,"proposal":proposal}));continue;}
   c.goal_start(goal,&json!({"stimulus_id":stimulus,"raw_utterance":raw,"goal_origin":"USER","revision":current_revision,"action":proposal["action"]}));
   let versions=array(&proposal["targets"]).iter().filter_map(|id|id.as_str().and_then(|id|sources.get(id)).map(|s|(s["id"].as_str().unwrap().to_owned(),s["revision"].clone()))).collect::<serde_json::Map<String,Value>>();
   let titles=array(&proposal["targets"]).iter().filter_map(|id|id.as_str().and_then(|id|sources.get(id)).and_then(|s|s["title"].as_str())).collect::<Vec<_>>().join(", ");
   let adopted=json!({"adoption_id":format!("{}-intent",stimulus),"resolved":true,"purpose":proposal["purpose"],"completion_condition":proposal["completion_condition"],"recipient":proposal["recipient"],"targets":proposal["targets"],"source_revisions":versions,"scope":proposal["purpose"],"handling":proposal["handling"],"text":format!("{}: {}",if titles.is_empty(){"현재 대화"}else{&titles},proposal["handling"].as_str().unwrap()),"raw_utterance":raw});c.progress(goal,stimulus,&adopted)?;adoptions.push(adopted.clone());
   if proposal["action"]=="CLOSE"{let out=json!({"stimulus_id":stimulus,"revision":current_revision,"text":proposal["handling"],"raw_utterance":raw,"content_contract_checked":true,"checks":["actual_user_intent_adopted","no_delegation_requested"],"phase":"CLOSED_WITHOUT_HANDOFF"});c.complete(goal,&out)?;outputs.push(out);continue;}
   let mut mandatory=json!({"delegation_id":event["delegation_id"],"delegation_revision":event["delegation_revision"],"request_revision":state["request_revision"],"task_id":state["task_id"],"goal_id":goal,"purpose":proposal["purpose"],"completion_condition":proposal["completion_condition"],"artifact_type":proposal["artifact_type"],"targets":proposal["targets"],"constraints":state["constraints"],"exclusions":state["exclusions"],"allowed_actions":state["allowed_actions"],"already_completed_actions":state["already_completed_actions"],"unknown_actions":state["unknown_actions"],"required_source_ids":state["required_source_ids"],"condition_revision":state["condition_revision"],"recipient":proposal["recipient"],"access_epoch":state["access_epoch"],"revoked_sources":sources.values().filter(|s|s["revoked"].as_bool()==Some(true)).map(|s|s["id"].clone()).collect::<Vec<_>>()});
   let missing:Vec<Value>=array(&state["required_source_ids"]).into_iter().filter(|id|!id.as_str().and_then(|id|sources.get(id)).map(|s|s["revoked"].as_bool()!=Some(true)).unwrap_or(false)).collect();mandatory["disposition"]=json!(if missing.is_empty(){"AUTHORIZED"}else{"BLOCKED_REQUIRED_SOURCE"});mandatory["missing_required_sources"]=json!(missing);
   if !missing.is_empty(){c.fail(goal,&json!({"stimulus_id":stimulus,"reason":"MISSING_REQUIRED_CURRENT_SOURCE","missing":missing}));continue;}
   let capsule=match handoff::build(&mut c,variant,&mandatory,&sources,&mut common_evidence,&record){Ok(capsule)=>capsule,Err(reason)=>{c.fail(goal,&json!({"stimulus_id":stimulus,"reason":reason}));continue;}};
   let contract=json!({"mandatory":mandatory,"manifest":catalog(&sources).into_iter().filter(|s|s["revoked"].as_bool()!=Some(true)).collect::<Vec<_>>(),"capsule":capsule,"detail_selection_authority":if variant=="C"{"RECEIVER"}else{"VIA_WITH_RECEIVER_FOLLOWUP_READS"},"source_vector":catalog(&sources)});c.event("HANDOFF_ADMISSION",&contract);handoffs.push(contract.clone());c.event("AGENT_INGRESS",&json!({"goal_id":goal,"stimulus_id":stimulus,"delegation_id":event["delegation_id"]}));
   c.event("DOWNSTREAM_SHIM_ACCEPTED",&json!({"goal_id":goal,"stimulus_id":stimulus,"shim_id":event["delegation_id"],"profile":"LOGICAL_MODEL_BACKED_RECEIVER_SHIM"}));let received=receiver::execute(&mut c,event,&contract,&sources);c.event("DOWNSTREAM_SHIM_RETURN",&json!({"goal_id":goal,"stimulus_id":stimulus,"shim_id":event["delegation_id"],"status":if received.is_ok(){"RETURNED"}else{"FAILED"}}));let r=received?;receipts.push(r["receipt"].clone());if r["completed"]!=true{c.fail(goal,&json!({"stimulus_id":stimulus,"reason":"RECEIVER_BOUNDED_COMPLETION_FAILED","details":r}));continue;}
   let out=json!({"goal_id":goal,"stimulus_id":stimulus,"revision":current_revision,"text":r["result"]["text"],"receiver":r["result"],"phase":"RESULT","raw_utterance":raw,"content_contract_checked":true,"checks":["current_source_access_and_revision","actually_supplied_span_quote","separate_actual_display_and_source_claims","non_echo_bounded_result"],"oracle_semantic_correctness_claimed":false});c.complete(goal,&out)?;outputs.push(out);
  }
  _=>return Err(format!("unknown dp05 event {}",event["kind"])),
 }ctx.logical_buffer("dp05_source_registry",sources.values().map(|s|s.to_string().len()).sum(),"STATE");ctx.logical_buffer("dp05_common_acquired",serde_json::to_vec(&common_evidence).unwrap().len(),"STATE");ctx.logical_buffer("dp05_work_record",record.to_string().len(),"STATE");}
 Ok(json!({"adoptions":adoptions,"outputs":outputs,"handoffs":handoffs,"receiver_receipts":receipts,"production_state":record,"fixture_class":"CONSTRUCTED_SYNTHETIC_POC"}))
}
